package com.hbm.network.rtty.autocal;
import com.hbm.api.computer.*;
import com.hbm.multiblock.MuffledMachine;
import com.hbm.network.rtty.autocal.script.*;
import com.hbm.network.rtty.autocal.script.IParse.*;
import java.util.Locale;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
/** Original AUTOCAL execution loop and full parser context;100-instruction brake, source skip/error/reboot behavior. */
public final class AutocalEntity extends BlockEntity implements ComputerControl,MuffledMachine {
 public boolean isOn,ignoreError,autoReboot,muffled,tilted;public String[] script=new String[0];public final IParse parser=new ParseMSES1Ext1();public ParseContext ctx;public final String[] history={"","","","","",""};
 public AutocalEntity(BlockPos pos,BlockState state){super(AutocalContent.ENTITY.get(),pos,state);}
 private ParseContext context(){if(ctx==null)ctx=new ParseContext(level);if(ctx.world!=level)ctx.world=level;return ctx;}
 public static void tick(Level level,BlockPos pos,BlockState state,AutocalEntity autocal){if(level instanceof ServerLevel server)autocal.serverTick(server);}
 private void serverTick(ServerLevel server){if(server.getGameTime()%60==0)setChanged();context();if(!isOn&&autoReboot)isOn=true;if(isOn){int emergencyBrake=100;for(int i=0;i<ctx.clockSpeed&&emergencyBrake>0;i++){emergencyBrake--;if(ctx.current==script.length){stop("Program has terminated");break;}if(ctx.current<0||ctx.current>=script.length){stop("Program index is out of bounds");break;}try{int index=ctx.current++;String line=script[index];EnumStatementReturn result=parser.eval(ctx,line);if(result!=EnumStatementReturn.SKIP)pushMsg(index+": "+line);history[0]="Buffer: "+ctx.readBuffer();if(result==EnumStatementReturn.END_TICK)break;if(result==EnumStatementReturn.SHUTDOWN)stop("Program requested shutdown");if(!ignoreError){switch(result){case UNRECOGNIZED_COMMAND->stop("Unrecognized command");case PARAMETER_MISSING->stop("Parameter missing");case PARAMETER_OOB->stop("Parameter out of bounds");case PARAMETER_PARSE_ERROR->stop("Error parsing parameter");case NO_DESTINATION->stop("Missing JMP destination");case ARITHMETIC_EXCEPTION->stop("Arithmetic error");case BUFFER_EMPTY->stop("Buffer empty");case UNDEFINED->stop("Undefined behavior");case STACK_EXCEEDED->stop("Stack exceeded capacity");default->{}}}else if(result.error)ctx.variables.putString("last_error",result.name().toLowerCase(Locale.US));if(result==EnumStatementReturn.SKIP)i--;}catch(Exception ignored){stop("Evaluation unsuccessful");}}}
  var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<225)player.connection.send(packet);dispatchScope.commit();}
 }
 public void pushMsg(String message){for(int i=2;i<history.length;i++)history[i-1]=history[i];history[history.length-1]=message;}
 public void stop(String reason){isOn=false;context().turnOff();pushMsg(reason);}
 private void script(String payload){context().jmp.clear();script=payload.split("\n");for(int i=0;i<script.length;i++){script[i]=script[i].trim();parser.generateJumpPoints(ctx,script[i],i);}if(isOn)stop("Script has changed");}
 public void control(CompoundTag data){if(data.contains("on")){if(isOn)stop("User requested shutdown");else isOn=true;}if(data.contains("ignore"))ignoreError=!ignoreError;if(data.contains("auto"))autoReboot=!autoReboot;if(data.contains("payload"))script(data.getString("payload"));setChanged();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putBoolean("isOn",isOn);tag.putBoolean("ignoreError",ignoreError);tag.putBoolean("autoReboot",autoReboot);var lines=new ListTag();for(String line:script)lines.add(StringTag.valueOf(line));tag.put("script",lines);context().writeToNBT(tag);flags(tag);}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);isOn=tag.getBoolean("isOn");ignoreError=tag.getBoolean("ignoreError");autoReboot=tag.getBoolean("autoReboot");var lines=tag.getList("script",Tag.TAG_STRING);script=new String[lines.size()];for(int i=0;i<script.length;i++)script[i]=lines.getString(i);ctx=new ParseContext(null);ctx.readFromNBT(tag,script,parser);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 private void flags(CompoundTag tag){tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putBoolean("isOn",isOn);tag.putBoolean("ignoreError",ignoreError);tag.putBoolean("autoReboot",autoReboot);for(int i=0;i<history.length;i++)tag.putString("history"+i,history[i]);flags(tag);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){isOn=tag.getBoolean("isOn");ignoreError=tag.getBoolean("ignoreError");autoReboot=tag.getBoolean("autoReboot");for(int i=0;i<history.length;i++)history[i]=tag.getString("history"+i);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public String computerType(){return "radio_autocal";}@Override public String[] computerMethods(){return new String[]{"setBuffer","getBuffer","setScript","getScript","setState","getState","setIgnoreError","getIgnoreError","setAutoReboot","getAutoReboot","getHistory"};}
 @Override public Object[] callComputer(String method,ComputerArguments args){switch(method){case "setBuffer"->{if(ctx==null)return new Object[0];boolean full=ctx.writeBuffer(args.checkString(0));setChanged();return new Object[]{full};}case "getBuffer"->{return new Object[]{ctx==null?"":ctx.readBuffer()};}case "setScript"->script(args.checkString(0));case "getScript"->{String joined="";for(String line:script)joined+=line+"\n";return new Object[]{joined};}case "setState"->{if(args.checkBoolean(0))isOn=true;else stop("User requested shutdown");}case "getState"->{return new Object[]{isOn};}case "setIgnoreError"->ignoreError=args.checkBoolean(0);case "getIgnoreError"->{return new Object[]{ignoreError};}case "setAutoReboot"->autoReboot=args.checkBoolean(0);case "getAutoReboot"->{return new Object[]{autoReboot};}case "getHistory"->{int i=args.checkInteger(0);return i>=0&&i<history.length?new Object[]{history[i]}:new Object[0];}default->throw new ComputerException("No such method: "+method);}setChanged();return new Object[0];}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;}
}
